 static int checks;static JdbcTemplate db;static Clock clock=Clock.fixed(Instant.parse("2026-10-20T01:00:00Z"),ZoneOffset.UTC);static JsonCodec json=new JsonCodec();static AssetService assets;static DraftService drafts;static UsagePolicyService limits;static AiMeteringService meter;static OperationsService ops;static ManagedStorage disk;static AdminPrincipal admin;static LocalDateTime now=LocalDateTime.now(clock);
