 static void denied(Runnable task,String code){try{task.run();throw new AssertionError("Expected "+code);}catch(Problem p){ok(code.equals(p.code()),"Expected "+code+" got "+p.code());}}
 static Owner owner(String name){db.update("INSERT INTO ap_account(account_type,system_role,status,display_name,contact_email,phone_e164,created_at,updated_at) VALUES('CUSTOMER','CUSTOMER','ACTIVE',?,?,'+821012345678',?,?)",name,name+"@example.invalid",now,now);long id=db.queryForObject("SELECT id FROM ap_account WHERE display_name=?",Long.class,name);db.update("INSERT INTO ap_email_credential(account_id,login_email,password_hash,email_verified_at) VALUES(?,?,?,?)",id,name+"@example.invalid","test",now);db.update("INSERT INTO ap_workspace(owner_account_id,name,kind,plan_code,created_at,updated_at) VALUES(?,?,'CUSTOMER','FREE',?,?)",id,name,now,now);long w=db.queryForObject("SELECT id FROM ap_workspace WHERE owner_account_id=?",Long.class,id);db.update("INSERT INTO ap_workspace_member(workspace_id,account_id,member_role,created_at) VALUES(?,?,'OWNER',?)",w,id,now);db.update("INSERT INTO ap_business_scope(workspace_id,name,is_default,created_at,updated_at) VALUES(?,'사업',TRUE,?,?)",w,now,now);long b=db.queryForObject("SELECT id FROM ap_business_scope WHERE workspace_id=?",Long.class,w);return new Owner(new CustomerPrincipal(id,0,0,"EMAIL",name),w,b);}
 static String project(Owner o,String workflow){SecurityContextHolder.getContext().setAuthentication(UsernamePasswordAuthenticationToken.authenticated(o.user(),"",o.user().authorities()));return (String)drafts.create(o.user(),new DraftService.Create(o.business(),workflow,"작업 "+UUID.randomUUID())).get("id");}
